    function getCurrentGameMeta() {
      const sel = document.getElementById("gameSelect");
      const opt = sel.options[sel.selectedIndex];
      return {
        id: sel.value,
        name: opt.text,
        mode: opt.getAttribute("data-mode") || "coaster"
      };
    }

    function getCurrentRecord() {
      const meta = getCurrentGameMeta();
      if (!appStore.games[meta.id]) {
        appStore.games[meta.id] = createEmptyGameRecord(meta.id, meta.name, meta.mode);
      }
      return appStore.games[meta.id];
    }

    function formatNowHHMM() {
      const now = new Date();
      return now.toTimeString().slice(0, 5);
    }

    function formatDurationMMSS(totalSec) {
      const sec = Math.max(0, Math.round(totalSec));
      const m = Math.floor(sec / 60);
      const s = sec % 60;
      return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
    }

    function timeStrToMinutes(hhmm) {
      if (!hhmm || !hhmm.includes(":")) return null;
      const parts = hhmm.split(":");
      return parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
    }

    function computeGameMetrics(rec) {
      const totalDowntimeMin = rec.downtimes.reduce((acc, d) => acc + (d.durationMin || 0), 0);
      let grossMin = 0;
      if (rec.openTime) {
        const startM = timeStrToMinutes(rec.openTime);
        const endM = rec.closeTime ? timeStrToMinutes(rec.closeTime) : timeStrToMinutes(formatNowHHMM());
        if (startM !== null && endM !== null && endM >= startM) {
          grossMin = endM - startM;
        }
      }
      const netMin = Math.max(0, grossMin - totalDowntimeMin);
      const totalCycles = rec.cycles.reduce((acc, c) => acc + (c.bulkCycles ? c.bulkCycles : 1), 0);
      const totalPax = rec.cycles.reduce((acc, c) => acc + (c.pax || 0), 0);
      const validCycles = rec.cycles.filter(c => (c.durationSec || 0) > 0);
      const totalCycleSec = validCycles.reduce((acc, c) => acc + (c.durationSec || 0), 0);
      const avgCycleSec = validCycles.length > 0 ? Math.round(totalCycleSec / validCycles.length) : 0;

      return {
        grossMin,
        netMin,
        totalDowntimeMin,
        totalCycles,
        totalPax,
        avgCycleSec
      };
    }

