    // Khởi tạo đúng bộ số liệu như trên bảng mẫu image_5b6f17.png
    function populateSampleData() {
      const today = new Date().toISOString().slice(0, 10);
      ALL_GAMES.forEach(g => {
        const rec = createEmptyGameRecord(g.id, g.name, g.mode);
        rec.date = today;
        rec.staff = "Nguyễn Văn An";
        rec.openTime = "08:00";
        rec.closeTime = null;
        rec.downtimes = [];
        rec.cycles = [];

        if (g.initPax > 0) {
          if (g.id === "THAP_ROI") {
            rec.downtimes = [{ id: 1, reason: "Thời tiết mưa", start: "10:00", end: "10:25", durationMin: 25, note: "Mưa rào nhẹ" }];
          }
          const defaultSubArea = (g.subAreas && g.subAreas.length > 0) ? g.subAreas[0] : "";
          const secondSubArea = (g.subAreas && g.subAreas.length > 1) ? g.subAreas[1] : defaultSubArea;
          const detailCycles = [
            { id: 201, cycleNo: 1, subArea: defaultSubArea, subType: "Đợt khách (Đón → Tiễn)", start: "08:35", end: "08:41", durationSec: 360, pax: Math.min(20, g.initPax) }
          ];
          const remPax = Math.max(0, g.initPax - detailCycles[0].pax);
          if (remPax > 0) {
            detailCycles.unshift({
              id: 200,
              cycleNo: 0,
              subArea: secondSubArea,
              subType: `Luỹ kế trong ca (${Math.max(1, g.initCycles - 1)} lượt)`,
              start: "08:00",
              end: "16:30",
              durationSec: 360,
              pax: remPax,
              bulkCycles: Math.max(1, g.initCycles - 1)
            });
          }
          detailCycles.forEach((c, idx) => { c.cycleNo = idx + 1; });
          rec.cycles = detailCycles;
        }
        appStore.games[g.id] = rec;
      });
      saveToLocalStorage();
    }

    // =========================================================================
    // HỆ THỐNG LƯU TRỮ DỮ LIỆU ĐA TẦNG (INDEXEDDB + LOCALSTORAGE + CLOUD SYNC)
    // =========================================================================
    const IDB_NAME = "SunWorldOperationsDB";
    const IDB_VERSION = 1;
    let idbInstance = null;
    let currentDbSubTab = "shifts";

    function initIndexedDB() {
      if (!window.indexedDB) return;
      const req = indexedDB.open(IDB_NAME, IDB_VERSION);
      req.onupgradeneeded = function(e) {
        const db = e.target.result;
        if (!db.objectStoreNames.contains("daily_snapshots")) {
          db.createObjectStore("daily_snapshots", { keyPath: "dateKey" });
        }
        if (!db.objectStoreNames.contains("app_kv")) {
          db.createObjectStore("app_kv", { keyPath: "key" });
        }
      };
      req.onsuccess = function(e) {
        idbInstance = e.target.result;
        syncCurrentStoreToIndexedDB();
      };
    }

    function syncCurrentStoreToIndexedDB() {
      if (!idbInstance) return;
      try {
        const tx = idbInstance.transaction(["app_kv", "daily_snapshots"], "readwrite");
        tx.objectStore("app_kv").put({
          key: STORAGE_KEY,
          updatedAt: new Date().toISOString(),
          data: appStore
        });
        const activeDate = document.getElementById("opDate")
          ? document.getElementById("opDate").value
          : new Date().toISOString().slice(0, 10);
        tx.objectStore("daily_snapshots").put({
          dateKey: activeDate,
          updatedAt: new Date().toISOString(),
          games: JSON.parse(JSON.stringify(appStore.games || {}))
        });
      } catch (err) {
        console.warn("IndexedDB sync warning:", err);
      }
    }

    function getAllArchivedRecords() {
      // Kết hợp kho lịch sử nhiều ngày (appStore.historyByDate) và dữ liệu ca hiện tại (appStore.games)
      if (!appStore.historyByDate) {
        appStore.historyByDate = {};
      }
      const activeDate = document.getElementById("opDate")
        ? document.getElementById("opDate").value
        : new Date().toISOString().slice(0, 10);

      const combinedByDate = {
        ...appStore.historyByDate,
        [activeDate]: appStore.games || {}
      };

      const shifts = [];
      const downtimes = [];
      const cycles = [];

      Object.keys(combinedByDate).sort().reverse().forEach(dateStr => {
        const gamesMap = combinedByDate[dateStr] || {};
        ALL_GAMES.forEach(g => {
          const rec = gamesMap[g.id];
          if (!rec) return;
          const m = computeGameMetrics(rec);
          const hasActivity = m.totalCycles > 0 || m.totalDowntimeMin > 0 || rec.closeTime;
          if (!hasActivity && g.initPax === 0) return;

          const shiftId = `CA_${ (rec.date || dateStr).replace(/-/g, "") }_${g.id}`;
          shifts.push({
            shiftId,
            date: rec.date || dateStr,
            gameId: g.id,
            gameName: g.name,
            staff: rec.staff || "Nguyễn Văn An",
            openTime: rec.openTime || "08:00",
            closeTime: rec.closeTime || "Đang mở",
            netMin: m.netMin,
            totalDowntimeMin: m.totalDowntimeMin,
            totalCycles: m.totalCycles,
            totalPax: m.totalPax
          });

          (rec.downtimes || []).forEach(d => {
            downtimes.push({
              id: `DT_${d.id}`,
              date: rec.date || dateStr,
              gameId: g.id,
              gameName: g.name,
              staff: rec.staff || "Nguyễn Văn An",
              reason: d.reason,
              start: d.start,
              end: d.end,
              durationMin: d.durationMin,
              note: d.note || ""
            });
          });

          (rec.cycles || []).forEach(c => {
            cycles.push({
              id: `CY_${g.id}_${c.id}`,
              date: rec.date || dateStr,
              gameId: g.id,
              gameName: g.name,
              subArea: c.subArea || "",
              cycleNo: c.cycleNo,
              subType: c.subType,
              start: c.start,
              end: c.end,
              durationSec: c.durationSec || 0,
              pax: c.pax || 0,
              bulkCycles: c.bulkCycles || 1
            });
          });
        });
      });

      return { shifts, downtimes, cycles, dates: Object.keys(combinedByDate).sort().reverse() };
    }

    function commitCurrentDayToArchive() {
      if (!appStore.historyByDate) appStore.historyByDate = {};
      const activeDate = document.getElementById("opDate").value || new Date().toISOString().slice(0, 10);
      appStore.historyByDate[activeDate] = JSON.parse(JSON.stringify(appStore.games || {}));
      saveToLocalStorage();
      syncCurrentStoreToIndexedDB();
      pushNotification(`Đã chốt và lưu toàn bộ dữ liệu ngày ${activeDate} vào Kho dữ liệu lịch sử.`);
      renderStorageExplorer();
      showAppToast(`Đã lưu toàn bộ dữ liệu vận hành ngày ${activeDate} vào Kho lưu trữ lịch sử thành công!`);
    }

    function switchDbSubTab(tab) {
      currentDbSubTab = tab;
      document.getElementById("dbTabShifts").classList.toggle("active", tab === "shifts");
      document.getElementById("dbTabDowntimes").classList.toggle("active", tab === "downtimes");
      document.getElementById("dbTabCycles").classList.toggle("active", tab === "cycles");
      document.getElementById("dbTabCloud").classList.toggle("active", tab === "cloud");

      document.getElementById("dbPanelShifts").style.display = tab === "shifts" ? "block" : "none";
      document.getElementById("dbPanelDowntimes").style.display = tab === "downtimes" ? "block" : "none";
      document.getElementById("dbPanelCycles").style.display = tab === "cycles" ? "block" : "none";
      document.getElementById("dbPanelCloud").style.display = tab === "cloud" ? "block" : "none";
      document.getElementById("dbFilterBar").style.display = tab === "cloud" ? "none" : "grid";
      renderStorageExplorer();
    }

    function renderStorageExplorer() {
      const dbData = getAllArchivedRecords();

      // Cập nhật dropdown lọc Ngày & Trò chơi
      const dateSel = document.getElementById("dbFilterDate");
      if (dateSel) {
        const prevDateVal = dateSel.value || "ALL";
        dateSel.innerHTML = `<option value="ALL">Tất cả các ngày (${dbData.dates.length} ngày)</option>` +
          dbData.dates.map(d => `<option value="${d}">Ngày ${d}</option>`).join("");
        if (dbData.dates.includes(prevDateVal)) dateSel.value = prevDateVal;
      }

      const gameSel = document.getElementById("dbFilterGame");
      if (gameSel && gameSel.options.length <= 1) {
        gameSel.innerHTML = `<option value="ALL">Tất cả trò chơi (Toàn khu)</option>` +
          ALL_GAMES.map(g => `<option value="${g.id}">${g.name}</option>`).join("");
      }

      const fDate = dateSel ? dateSel.value : "ALL";
      const fGame = gameSel ? gameSel.value : "ALL";
      const fArea = document.getElementById("dbFilterSubArea") ? document.getElementById("dbFilterSubArea").value : "ALL";

      const filteredShifts = dbData.shifts.filter(s =>
        (fDate === "ALL" || s.date === fDate) &&
        (fGame === "ALL" || s.gameId === fGame)
      );

      const filteredDowntimes = dbData.downtimes.filter(d =>
        (fDate === "ALL" || d.date === fDate) &&
        (fGame === "ALL" || d.gameId === fGame)
      );

      const filteredCycles = dbData.cycles.filter(c =>
        (fDate === "ALL" || c.date === fDate) &&
        (fGame === "ALL" || c.gameId === fGame) &&
        (fArea === "ALL" || c.subArea === fArea)
      );

      // Cập nhật 4 thẻ KPI của Kho Lưu Trữ
      const totalCyclesCount = filteredCycles.reduce((acc, c) => acc + (c.bulkCycles || 1), 0);
      const totalPaxSum = filteredCycles.reduce((acc, c) => acc + (c.pax || 0), 0);
      const totalDtMinSum = filteredDowntimes.reduce((acc, d) => acc + (d.durationMin || 0), 0);

      const elShiftsCount = document.getElementById("dbStatShiftsCount");
      if (elShiftsCount) {
        elShiftsCount.textContent = `${formatVNNumber(filteredShifts.length)} ca trực`;
        document.getElementById("dbStatDaysCount").textContent = `Đang lưu trữ: ${dbData.dates.length} ngày vận hành`;
        document.getElementById("dbStatCyclesCount").textContent = `${formatVNNumber(totalCyclesCount)} lượt`;
        document.getElementById("dbStatPaxSum").textContent = `Tổng khách: ${formatVNNumber(totalPaxSum)} khách`;
        document.getElementById("dbStatDowntimesCount").textContent = `${formatVNNumber(filteredDowntimes.length)} sự cố`;
        document.getElementById("dbStatDowntimeMinSum").textContent = `Tổng phút dừng: ${formatVNNumber(totalDtMinSum)} phút`;
      }

      // Render Bảng 1: SHIFTS_DB
      const shBody = document.getElementById("dbTableShiftsBody");
      if (shBody) {
        if (filteredShifts.length === 0) {
          shBody.innerHTML = `<tr><td colspan="11" class="text-center" style="padding:14px; color:var(--text-muted);">Không có bản ghi ca trực phù hợp với bộ lọc</td></tr>`;
        } else {
          shBody.innerHTML = filteredShifts.map(s => {
            const nh = Math.floor(s.netMin / 60);
            const nm = s.netMin % 60;
            return `
              <tr style="cursor:pointer;" onclick="selectGameAndView('${s.gameId}')">
                <td style="font-weight:700; font-size:0.76rem; color:var(--text-muted);">${s.shiftId}</td>
                <td>${s.date}</td>
                <td><strong>${s.gameName}</strong></td>
                <td>${s.staff}</td>
                <td>${s.openTime}</td>
                <td>${s.closeTime}</td>
                <td class="text-right" style="font-weight:700;">${nh}h ${String(nm).padStart(2, "0")}p</td>
                <td class="text-right" style="font-weight:700; color:${s.totalDowntimeMin > 0 ? 'var(--danger)' : 'var(--text-muted)'};">${s.totalDowntimeMin} phút</td>
                <td class="text-right" style="font-weight:700;">${formatVNNumber(s.totalCycles)}</td>
                <td class="text-right" style="font-weight:800; color:var(--primary);">${formatVNNumber(s.totalPax)}</td>
                <td class="text-center"><span class="sync-pill-ok">✓ Đã lưu DB</span></td>
              </tr>
            `;
          }).join("");
        }
      }

      // Render Bảng 2: DOWNTIMES_DB
      const dtBody = document.getElementById("dbTableDowntimesBody");
      if (dtBody) {
        if (filteredDowntimes.length === 0) {
          dtBody.innerHTML = `<tr><td colspan="9" class="text-center" style="padding:14px; color:var(--text-muted);">Chưa có bản ghi ngừng vận hành trong bộ lọc này</td></tr>`;
        } else {
          dtBody.innerHTML = filteredDowntimes.map(d => `
            <tr>
              <td style="font-weight:700; font-size:0.76rem; color:var(--text-muted);">${d.id}</td>
              <td>${d.date}</td>
              <td><strong>${d.gameName}</strong></td>
              <td>${d.staff}</td>
              <td><span class="badge badge-general">${d.reason}</span></td>
              <td>${d.start}</td>
              <td>${d.end}</td>
              <td class="text-right" style="font-weight:800; color:var(--danger);">${d.durationMin} phút</td>
              <td>${d.note}</td>
            </tr>
          `).join("");
        }
      }

      // Render Bảng 3: CYCLES_DB
      const cyBody = document.getElementById("dbTableCyclesBody");
      if (cyBody) {
        if (filteredCycles.length === 0) {
          cyBody.innerHTML = `<tr><td colspan="10" class="text-center" style="padding:14px; color:var(--text-muted);">Không có bản ghi lượt chơi phù hợp với bộ lọc</td></tr>`;
        } else {
          cyBody.innerHTML = filteredCycles.map(c => `
            <tr>
              <td style="font-weight:700; font-size:0.75rem; color:var(--text-muted);">${c.id}</td>
              <td>${c.date}</td>
              <td><strong>${c.gameName}</strong></td>
              <td>${c.subArea ? `<span class="subarea-Tag">${c.subArea}</span>` : '<span style="color:var(--text-muted);">Toàn khu</span>'}</td>
              <td><strong>#${c.cycleNo}</strong></td>
              <td>${c.subType}</td>
              <td>${c.start}</td>
              <td>${c.end}</td>
              <td class="text-right" style="font-weight:700;">${formatDurationMMSS(c.durationSec)}</td>
              <td class="text-right" style="font-weight:800; color:var(--primary);">${formatVNNumber(c.pax)} khách</td>
            </tr>
          `).join("");
        }
      }
    }

    function saveCloudWebhookUrl() {
      const url = document.getElementById("cloudWebhookUrlInput").value.trim();
      safeSetStorage("SUNWORLD_CLOUD_WEBHOOK_URL", url);
      const pill = document.getElementById("cloudSyncStatusText");
      if (url) {
        pill.className = "sync-pill-ok";
        pill.textContent = "● Đã kết nối Webhook URL (Sẵn sàng đồng bộ)";
      } else {
        pill.className = "sync-pill-pending";
        pill.textContent = "● Chưa cấu hình URL Cloud (Đang lưu Offline an toàn)";
      }
    }

    async function syncToCloudWebhook() {
      const dbData = getAllArchivedRecords();
      const urlInput = document.getElementById("cloudWebhookUrlInput");
      const webhookUrl = urlInput ? urlInput.value.trim() : (safeGetStorage("SUNWORLD_CLOUD_WEBHOOK_URL") || "");

      syncCurrentStoreToIndexedDB();

      if (!webhookUrl) {
        switchScreen("storage");
        switchDbSubTab("cloud");
        showAppToast("Dữ liệu đã được lưu an toàn trong Kho dữ liệu nội bộ (IndexedDB + LocalStorage)!\n\nĐể đẩy tự động lên Google Sheets, bạn hãy dán đường dẫn Google Apps Script Webhook URL tại mục '4. Kết Nối Google Sheets / Sao Lưu File'.");
        return;
      }

      const pill = document.getElementById("cloudSyncStatusText");
      if (pill) {
        pill.className = "sync-pill-pending";
        pill.textContent = "⏳ Đang đồng bộ dữ liệu lên Google Sheets...";
      }

      try {
        await fetch(webhookUrl, {
          method: "POST",
          mode: "no-cors",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            exportedAt: new Date().toISOString(),
            operator: currentUserAccount,
            shifts: dbData.shifts,
            downtimes: dbData.downtimes,
            cycles: dbData.cycles
          })
        });
        const nowTime = new Date().toTimeString().slice(0, 8);
        if (pill) {
          pill.className = "sync-pill-ok";
          pill.textContent = `✓ Đã đồng bộ lên Google Sheets lúc ${nowTime}`;
        }
        pushNotification(`Đã đồng bộ ${dbData.shifts.length} ca trực và ${dbData.cycles.length} bản ghi lượt chơi lên Google Sheets.`);
        showAppToast("Đã gửi toàn bộ dữ liệu (Nhật ký ca, Ngừng vận hành, Lượt chơi & Line/Rạp) lên Google Sheets thành công!");
      } catch (err) {
        if (pill) {
          pill.className = "sync-pill-pending";
          pill.textContent = "⚠️ Lỗi mạng khi đồng bộ Cloud — Dữ liệu vẫn được bảo toàn Offline";
        }
        showAppToast("Không thể kết nối tới URL Cloud (do mất mạng hoặc sai URL). Toàn bộ dữ liệu vẫn được lưu an toàn trong bộ nhớ máy!");
      }
    }

    function exportCurrentDbTableCSV() {
      const dbData = getAllArchivedRecords();
      const today = new Date().toISOString().slice(0, 10);
      let lines = [];
      let filename = `SunWorld_Database_${currentDbSubTab}_${today}.csv`;

      if (currentDbSubTab === "shifts") {
        lines.push(["Ma_Ca", "Ngay", "Ma_Tro_Choi", "Ten_Tro_Choi", "Nhan_Vien", "Gio_Mo_Cua", "Gio_Dong_Cua", "Gio_VH_Thuc_Te_Phut", "Tong_Phut_Dung", "Tong_So_Luot", "Tong_Khach"]);
        dbData.shifts.forEach(s => {
          lines.push([s.shiftId, s.date, s.gameId, `"${s.gameName}"`, `"${s.staff}"`, s.openTime, s.closeTime, s.netMin, s.totalDowntimeMin, s.totalCycles, s.totalPax]);
        });
      } else if (currentDbSubTab === "downtimes") {
        lines.push(["Ma_Dung", "Ngay", "Ten_Tro_Choi", "Nhan_Vien", "Loai_Dung", "Bat_Dau", "Ket_Thuc", "So_Phut_Dung", "Ghi_Chu"]);
        dbData.downtimes.forEach(d => {
          lines.push([d.id, d.date, `"${d.gameName}"`, `"${d.staff}"`, `"${d.reason}"`, d.start, d.end, d.durationMin, `"${(d.note || "").replace(/"/g, '""')}"`]);
        });
      } else {
        lines.push(["Ma_Luot", "Ngay", "Ten_Tro_Choi", "Khu_Vuc_Line_Rap", "Luot_So", "Phan_Loai", "Bat_Dau", "Ket_Thuc", "Chu_Ky_Giay", "So_Khach"]);
        dbData.cycles.forEach(c => {
          lines.push([c.id, c.date, `"${c.gameName}"`, `"${c.subArea}"`, c.cycleNo, `"${c.subType}"`, c.start, c.end, c.durationSec, c.pax]);
        });
      }

      const csvContent = "\uFEFF" + lines.map(r => r.join(",")).join("\n");
      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }

    function exportFullDatabaseJSON() {
      const today = new Date().toISOString().slice(0, 10);
      const backupPayload = {
        app: "Sun World Operations Database",
        version: STORAGE_KEY,
        exportedAt: new Date().toISOString(),
        appStore: appStore
      };
      const blob = new Blob([JSON.stringify(backupPayload, null, 2)], { type: "application/json;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `SunWorld_FullDatabase_Backup_${today}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }

    function importFullDatabaseJSON(event) {
      const file = event.target.files && event.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = function(e) {
        try {
          const parsed = JSON.parse(e.target.result);
          const importedStore = parsed.appStore || parsed;
          if (!importedStore || !importedStore.games) {
            showAppToast("File JSON không đúng cấu trúc dữ liệu của ứng dụng!");
            return;
          }
          appStore = importedStore;
          saveToLocalStorage();
          syncCurrentStoreToIndexedDB();
          onGameChange();
          renderStorageExplorer();
          pushNotification(`Đã khôi phục cơ sở dữ liệu từ file ${file.name} thành công.`);
          showAppToast("Đã nhập và khôi phục toàn bộ cơ sở dữ liệu thành công!");
        } catch (err) {
          showAppToast("Lỗi đọc file JSON: " + err.message);
        }
      };
      reader.readAsText(file);
    }

    function copyAppsScriptCode() {
      const code = document.getElementById("appsScriptCodeBlock").textContent;
      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(code).catch(() => {});
        }
        const ta = document.createElement("textarea");
        ta.value = code;
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        document.body.removeChild(ta);
      } catch (e) {}
      showAppToast("Đã sao chép mã Google Apps Script! Bạn có thể dán trực tiếp vào mục Extensions -> Apps Script trên file Google Sheets của mình.");
    }

    function saveToLocalStorage() {
      safeSetStorage(STORAGE_KEY, JSON.stringify(appStore));
      syncCurrentStoreToIndexedDB();
      const badge = document.getElementById("dbLastSavedBadge");
      if (badge) {
        badge.textContent = `● Đã lưu tự động lúc ${new Date().toTimeString().slice(0, 8)}`;
      }
    }

    function saveCurrentState() {
      const rec = getCurrentRecord();
      rec.date = document.getElementById("opDate").value;
      rec.staff = document.getElementById("staffName").value;
      saveToLocalStorage();
      renderAll();
    }

    function syncShiftDropdownsFromRecord(rec) {
      const openH = document.getElementById("openHourSelect");
      const openM = document.getElementById("openMinuteSelect");
      const closeH = document.getElementById("closeHourSelect");
      const closeM = document.getElementById("closeMinuteSelect");

      if (rec.openTime && rec.openTime.includes(":")) {
        const [oh, om] = rec.openTime.split(":");
        openH.value = oh;
        openM.value = om;
      } else {
        openH.value = "";
        openM.value = "";
      }

      if (rec.closeTime && rec.closeTime.includes(":")) {
        const [ch, cm] = rec.closeTime.split(":");
        closeH.value = ch;
        closeM.value = cm;
      } else {
        closeH.value = "";
        closeM.value = "";
      }
    }

    function onShiftSelectChange(type) {
      const rec = getCurrentRecord();
      if (type === "open") {
        let h = document.getElementById("openHourSelect").value;
        let m = document.getElementById("openMinuteSelect").value;
        if (h && !m) {
          m = "00";
          document.getElementById("openMinuteSelect").value = "00";
        } else if (!h && m) {
          h = "08";
          document.getElementById("openHourSelect").value = "08";
        }
        rec.openTime = (h && m) ? `${h}:${m}` : null;
      } else {
        let h = document.getElementById("closeHourSelect").value;
        let m = document.getElementById("closeMinuteSelect").value;
        if (h && !m) {
          m = "00";
          document.getElementById("closeMinuteSelect").value = "00";
        } else if (!h && m) {
          rec.closeTime = null;
          document.getElementById("closeMinuteSelect").value = "";
          saveToLocalStorage();
          renderAll();
          return;
        }
        rec.closeTime = (h && m) ? `${h}:${m}` : null;
      }
      saveToLocalStorage();
      renderAll();
    }

    function onGameChange() {
      const meta = getCurrentGameMeta();
      appStore.currentGameId = meta.id;
      document.getElementById("dashGameSelect").value = meta.id;
      const rec = getCurrentRecord();
      rec.mode = meta.mode;

      document.getElementById("currentRideHeaderLabel").textContent = `Trò chơi: ${meta.name}`;
      document.getElementById("cycleFrameBannerTitle").textContent = "⏱️ LƯỢT CHƠI";
      document.getElementById("cycleLockedGameBadge").textContent = `🎢 Trò chơi: ${meta.name}`;
      document.getElementById("dashboardBannerTitle").textContent = "📊 DASHBOARD";
      document.getElementById("opDate").value = rec.date || new Date().toISOString().slice(0, 10);
      document.getElementById("staffName").value = rec.staff || "";
      syncShiftDropdownsFromRecord(rec);
      switchModeUI(rec.mode);
      renderAll();
    }

    function onDashGameSelectChange() {
      const dashSel = document.getElementById("dashGameSelect");
      document.getElementById("gameSelect").value = dashSel.value;
      onGameChange();
    }

    function selectGameAndView(gameId) {
      document.getElementById("gameSelect").value = gameId;
      onGameChange();
    }

    function switchModeUI(mode) {
      const coasterPanel = document.getElementById("coasterModePanel");
      const batchPanel = document.getElementById("batchModePanel");
      const badge = document.getElementById("gameModeBadge");
      const cycleCardTitle = document.getElementById("cycleSectionCardTitle");
      const cycleModeBadge = document.getElementById("cycleModeIndicatorBadge");

      if (mode === "coaster") {
        coasterPanel.style.display = "block";
        batchPanel.style.display = "none";
        badge.className = "badge badge-coaster";
        badge.textContent = "Chế độ: Máng trượt (Bấm Xe đơn / Xe đôi = 1 chuyến)";
        if (cycleCardTitle) cycleCardTitle.textContent = "⏱️ Nhập Liệu Chuyến Xe Xuất Phát & Đo Giãn Cách Tải (Máng Trượt)";
        if (cycleModeBadge) {
          cycleModeBadge.className = "badge badge-coaster";
          cycleModeBadge.textContent = "Máng trượt: Bấm xuất xe tính 1 chuyến • Đo TG chuyến tiếp theo xuất phát";
        }
      } else {
        coasterPanel.style.display = "none";
        batchPanel.style.display = "block";
        badge.className = "badge badge-general";
        badge.textContent = "Chế độ: Trò chơi theo đợt (Đón khách → Tiễn khách)";
        if (cycleCardTitle) cycleCardTitle.textContent = "⏱️ Nhập Liệu Lượt Khách / Lượt & Đồng Hồ Chu Kỳ Lượt Chơi";
        if (cycleModeBadge) {
          cycleModeBadge.className = "badge badge-general";
          cycleModeBadge.textContent = "Trò chơi theo đợt: Đón khách → Tiễn khách";
        }
      }
    }

    let selectedDowntimeReasonValue = "Bảo trì";

    function selectDowntimeReason(reason) {
      selectedDowntimeReasonValue = reason;
      const buttons = document.querySelectorAll("#downtimeReasonButtons .reason-btn");
      buttons.forEach(btn => {
        btn.classList.toggle("active", btn.getAttribute("data-reason") === reason);
      });
      document.getElementById("selectedDowntimeBadge").textContent = `Đang chọn: ${reason}`;
    }

    function updateDowntimePreview() {
      const sh = document.getElementById("manDtStartH").value || "10";
      const sm = document.getElementById("manDtStartM").value || "15";
      const eh = document.getElementById("manDtEndH").value || "10";
      const em = document.getElementById("manDtEndM").value || "45";

      const startStr = `${sh}:${sm}`;
      const endStr = `${eh}:${em}`;
      document.getElementById("dtStartPreviewBadge").textContent = startStr;
      document.getElementById("dtEndPreviewBadge").textContent = endStr;

      const sMin = timeStrToMinutes(startStr);
      const eMin = timeStrToMinutes(endStr);
      const diff = (sMin !== null && eMin !== null && eMin > sMin) ? (eMin - sMin) : 0;
      document.getElementById("dtCalculatedDurationText").textContent = `${diff} phút`;
    }

    function addManualDowntime() {
      const rec = getCurrentRecord();
      const reason = selectedDowntimeReasonValue || "Bảo trì";
      const start = `${document.getElementById("manDtStartH").value}:${document.getElementById("manDtStartM").value}`;
      const end = `${document.getElementById("manDtEndH").value}:${document.getElementById("manDtEndM").value}`;
      const note = document.getElementById("manDtNote").value.trim() || "";

      const sMin = timeStrToMinutes(start);
      const eMin = timeStrToMinutes(end);
      if (sMin === null || eMin === null || eMin <= sMin) {
        showAppToast("Thời gian kết thúc dừng phải lớn hơn thời gian bắt đầu dừng!");
        return;
      }

      rec.downtimes.push({
        id: Date.now(),
        reason,
        start,
        end,
        durationMin: eMin - sMin,
        note
      });

      document.getElementById("manDtNote").value = "";
      saveToLocalStorage();
      renderAll();
    }

    function deleteDowntime(id) {
      const rec = getCurrentRecord();
      rec.downtimes = rec.downtimes.filter(d => d.id !== id);
      saveToLocalStorage();
      renderAll();
    }

    // Quản lý Khu vực vận hành đang chọn cho các trò chơi có chia Line / Rạp
    const GAME_SUB_AREAS = {
      "MANG_TRUOT_1": ["Line 1", "Line 2"],
      "MANG_TRUOT_2": ["Line 3", "Line 4"],
      "MANG_TRUOT_3": ["Line 5", "Line 6"],
      "AIRSHIP": ["Rạp 1", "Rạp 2"]
    };

    let selectedSubAreaByGame = {
      "MANG_TRUOT_1": "Line 1",
      "MANG_TRUOT_2": "Line 3",
      "MANG_TRUOT_3": "Line 5",
      "AIRSHIP": "Rạp 1"
    };

    function getActiveSubArea(gameId) {
      const areas = GAME_SUB_AREAS[gameId];
      if (!areas || areas.length === 0) return "";
      if (!selectedSubAreaByGame[gameId] || !areas.includes(selectedSubAreaByGame[gameId])) {
        selectedSubAreaByGame[gameId] = areas[0];
      }
      return selectedSubAreaByGame[gameId];
    }

    function selectSubArea(gameId, areaName) {
      selectedSubAreaByGame[gameId] = areaName;
      renderSubAreaSelector();
      renderAll();
    }

    function renderSubAreaSelector() {
      const rec = getCurrentRecord();
      const areas = GAME_SUB_AREAS[rec.gameId];
      const box = document.getElementById("subAreaSelectorContainer");
      const wrap = document.getElementById("subAreaButtonsWrap");
      const activeLabel = document.getElementById("subAreaActiveLabel");

      if (!areas || areas.length === 0) {
        box.style.display = "none";
        return;
      }

      box.style.display = "flex";
      const currentArea = getActiveSubArea(rec.gameId);
      activeLabel.textContent = `${rec.gameName} — Đang thao tác tại: ${currentArea}`;

      wrap.innerHTML = areas.map(area => {
        const isActive = area === currentArea;
        // Tính tổng số chuyến/lượt và tổng khách của riêng Line / Rạp này
        const areaCycles = rec.cycles.filter(c => (c.subArea || areas[0]) === area);
        const areaTripCount = areaCycles.reduce((acc, c) => acc + (c.bulkCycles ? c.bulkCycles : 1), 0);
        const areaPaxCount = areaCycles.reduce((acc, c) => acc + (c.pax || 0), 0);
        const unitLabel = rec.mode === "coaster" ? "chuyến" : "lượt";
        return `
          <button type="button" class="subarea-btn ${isActive ? 'active' : ''}" onclick="selectSubArea('${rec.gameId}', '${area}')">
            <span>${area}</span>
            <span class="subarea-stat-pill">${formatVNNumber(areaTripCount)} ${unitLabel} • ${formatVNNumber(areaPaxCount)} khách</span>
          </button>
        `;
      }).join("");
    }

    // Lưu mốc xuất phát gần nhất theo từng Line của Máng trượt (VD: MANG_TRUOT_1__Line 1)
    let coasterLastDispatchState = {};

    function formatNowHHMMSS() {
      return new Date().toTimeString().slice(0, 8);
    }

    // Chế độ Máng trượt: Bấm vào Xe Đơn / Xe Đôi là tính ngay 1 chuyến kèm Line vận hành (Line 1-2, Line 3-4, Line 5-6)
    function dispatchCoasterCar(paxCount) {
      const rec = getCurrentRecord();
      if (!rec.openTime) {
        rec.openTime = formatNowHHMM();
        syncShiftDropdownsFromRecord(rec);
      }

      const activeLine = getActiveSubArea(rec.gameId);
      const stateKey = activeLine ? `${rec.gameId}__${activeLine}` : rec.gameId;

      const nowMs = Date.now();
      const nowHHMMSS = formatNowHHMMSS();
      const prevState = coasterLastDispatchState[stateKey];

      // Tính thời gian từ chuyến trước đến chuyến tiếp theo xuất phát trên cùng Line (giây)
      let intervalSec = 0;
      if (prevState && prevState.timeMs) {
        intervalSec = Math.max(1, Math.round((nowMs - prevState.timeMs) / 1000));
      }

      const totalTripsBefore = rec.cycles.reduce((acc, c) => acc + (c.bulkCycles ? c.bulkCycles : 1), 0);
      const nextTripNo = totalTripsBefore + 1;
      const typeLabel = paxCount === 2 ? "Xe đôi (2 khách)" : "Xe đơn (1 khách)";

      rec.cycles.push({
        id: nowMs + Math.floor(Math.random() * 1000),
        cycleNo: nextTripNo,
        subArea: activeLine,
        subType: typeLabel,
        start: nowHHMMSS,
        end: "--",
        durationSec: intervalSec,
        pax: paxCount
      });

      coasterLastDispatchState[stateKey] = {
        timeMs: nowMs,
        timeStr: nowHHMMSS,
        tripNo: nextTripNo,
        subArea: activeLine,
        subType: typeLabel,
        lastIntervalSec: intervalSec
      };

      saveToLocalStorage();
      renderAll();
    }

    function renderActiveCoasterRuns() {
      const rec = getCurrentRecord();
      if (rec.mode !== "coaster") return;

      const activeLine = getActiveSubArea(rec.gameId);
      const stateKey = activeLine ? `${rec.gameId}__${activeLine}` : rec.gameId;
      const state = coasterLastDispatchState[stateKey];
      const timerEl = document.getElementById("coasterNextDispatchTimer");
      const infoEl = document.getElementById("coasterLastDispatchInfo");
      const statusLabel = document.getElementById("coasterIntervalStatusLabel");

      if (state && state.timeMs) {
        const elapsedSec = Math.max(0, Math.floor((Date.now() - state.timeMs) / 1000));
        timerEl.textContent = formatDurationMMSS(elapsedSec);
        statusLabel.textContent = `⏱️ [${activeLine}] ĐANG ĐẾM THỜI GIAN CHỜ CHUYẾN TIẾP THEO XUẤT PHÁT`;
        statusLabel.style.color = "#FFC928";
        infoEl.textContent = `Chuyến vừa xuất tại ${activeLine}: #${state.tripNo} (${state.subType}) lúc ${state.timeStr}`;
      } else {
        timerEl.textContent = "00:00";
        statusLabel.textContent = `⏱️ [${activeLine || 'Máng trượt'}] THỜI GIAN CHỜ CHUYẾN TIẾP THEO XUẤT PHÁT`;
        statusLabel.style.color = "#94a3b8";
        infoEl.textContent = `Đang chọn ${activeLine}: Bấm 'Xuất Xe Đơn' hoặc 'Xuất Xe Đôi' khi xe rời ga để tính 1 chuyến`;
      }

      // Tính các chỉ số công suất tải của Máng trượt
      const m = computeGameMetrics(rec);
      const singleCars = rec.cycles.filter(c => !c.bulkCycles && c.pax === 1).length;
      const doubleCars = rec.cycles.filter(c => !c.bulkCycles && c.pax === 2).length;

      document.getElementById("coasterSummaryTrips").textContent = `${formatVNNumber(m.totalCycles)} chuyến`;
      document.getElementById("coasterSummarySingleDouble").textContent = `Xe đơn: ${singleCars} | Xe đôi: ${doubleCars}`;

      const lastInterval = state && state.lastIntervalSec > 0
        ? state.lastIntervalSec
        : (rec.cycles.length > 0 ? rec.cycles[rec.cycles.length - 1].durationSec : 0);

      document.getElementById("coasterLastIntervalVal").textContent = lastInterval > 0
        ? `${formatDurationMMSS(lastInterval)} (${lastInterval}s)`
        : "Chuyến đầu";

      document.getElementById("coasterAvgIntervalVal").textContent = m.avgCycleSec > 0
        ? `${formatDurationMMSS(m.avgCycleSec)} (${m.avgCycleSec}s)`
        : "--:--";

      // Ước tính công suất tải 1 giờ dựa trên thời gian giãn cách trung bình (3600 giây / giãn cách)
      if (m.avgCycleSec > 0) {
        const carsPerHour = Math.round(3600 / m.avgCycleSec);
        const avgPaxPerCar = m.totalCycles > 0 ? (m.totalPax / m.totalCycles) : 1.5;
        const paxPerHour = Math.round(carsPerHour * avgPaxPerCar);
        document.getElementById("coasterThroughputVal").textContent = `${formatVNNumber(carsPerHour)} chuyến/giờ`;
        document.getElementById("coasterPaxThroughputVal").textContent = `~ ${formatVNNumber(paxPerHour)} khách/giờ`;
      } else {
        document.getElementById("coasterThroughputVal").textContent = "-- chuyến/giờ";
        document.getElementById("coasterPaxThroughputVal").textContent = "~ -- khách/giờ";
      }
    }

    // Chế độ Trò chơi khác
    function adjustBatchPax(delta) {
      const input = document.getElementById("batchPaxInput");
      const current = parseInt(input.value || "0", 10);
      input.value = Math.max(0, current + delta);
    }

    function startBatchCycle() {
      const rec = getCurrentRecord();
      if (!rec.openTime) {
        rec.openTime = formatNowHHMM();
        syncShiftDropdownsFromRecord(rec);
      }
      const activeArea = getActiveSubArea(rec.gameId);
      batchCycleState.running = true;
      batchCycleState.startTimeMs = Date.now();
      batchCycleState.startStr = formatNowHHMM();
      batchCycleState.subArea = activeArea;

      const areaPrefix = activeArea ? `[${activeArea}] ` : "";
      document.getElementById("btnStartBatchCycle").disabled = true;
      document.getElementById("btnFinishBatchCycle").disabled = false;
      document.getElementById("batchCycleLabel").textContent = `${areaPrefix}ĐANG ĐÓN KHÁCH & VẬN HÀNH LƯỢT #${rec.cycles.length + 1} (${rec.gameName})`;
      document.getElementById("batchCycleLabel").style.color = "#FFC928";
      document.getElementById("batchStartTimeInfo").textContent = `Bắt đầu đón khách lúc: ${batchCycleState.startStr}`;
      renderAll();
    }

    function finishBatchCycle() {
      if (!batchCycleState.running) return;
      const pax = parseInt(document.getElementById("batchPaxInput").value || "0", 10);
      if (pax <= 0) {
        showAppToast("Đã ghi nhận lượt chơi với 0 khách.");
      }

      const rec = getCurrentRecord();
      const activeArea = batchCycleState.subArea || getActiveSubArea(rec.gameId);
      const durationSec = Math.max(1, Math.round((Date.now() - batchCycleState.startTimeMs) / 1000));
      rec.cycles.push({
        id: Date.now(),
        cycleNo: rec.cycles.length + 1,
        subArea: activeArea,
        subType: "Đợt khách (Đón → Tiễn)",
        start: batchCycleState.startStr,
        end: formatNowHHMM(),
        durationSec: durationSec,
        pax: pax
      });

      batchCycleState.running = false;
      batchCycleState.startTimeMs = null;
      batchCycleState.startStr = null;

      document.getElementById("btnStartBatchCycle").disabled = false;
      document.getElementById("btnFinishBatchCycle").disabled = true;
      document.getElementById("batchStopwatchDisplay").textContent = "00:00";
      document.getElementById("batchCycleLabel").textContent = "SẴN SÀNG ĐÓN KHÁCH LƯỢT TIẾP THEO";
      document.getElementById("batchCycleLabel").style.color = "#94a3b8";
      document.getElementById("batchStartTimeInfo").textContent = "Đã lưu lượt chơi! Bấm 'Bắt đầu đón khách' cho lượt mới.";
      document.getElementById("batchPaxInput").value = 0;

      saveToLocalStorage();
      renderAll();
    }

    function deleteCycle(id) {
      const rec = getCurrentRecord();
      rec.cycles = rec.cycles.filter(c => c.id !== id);
      rec.cycles.forEach((c, idx) => { c.cycleNo = idx + 1; });
      saveToLocalStorage();
      renderAll();
    }

    // Render Khung hình 2: Báo cáo tổng quan (Dashboard)
    function renderDashboard() {
      const rec = getCurrentRecord();
      const m = computeGameMetrics(rec);

      // Pill tình trạng hoạt động của trò chơi trên Header
      const pill = document.getElementById("shiftStatusPill");
      const pillText = document.getElementById("shiftStatusText");
      if (activeDowntimeState) {
        pill.className = "status-pill status-paused";
        pillText.textContent = `TẠM DỪNG: ${activeDowntimeState.reason}`;
      } else if (rec.closeTime) {
        pill.className = "status-pill status-closed";
        pillText.textContent = `ĐÃ ĐÓNG CA (${rec.closeTime})`;
      } else if (rec.openTime) {
        pill.className = "status-pill status-running";
        pillText.textContent = `ĐANG HOẠT ĐỘNG (Mở: ${rec.openTime})`;
      } else {
        pill.className = "status-pill status-unopened";
        pillText.textContent = "CHƯA MỞ CA";
      }

      // Hiển thị badge giờ mở/đóng ở Khung hình 1
      document.getElementById("openTimeDisplay").textContent = rec.openTime || "--:--";
      document.getElementById("closeTimeDisplay").textContent = rec.closeTime || "--:--";

      // Dòng tóm tắt thông tin ca trên Dashboard
      document.getElementById("dashShiftMetaText").textContent =
        `Ngày: ${rec.date || "--"} | Nhân viên: ${rec.staff || "--"} | Mở cửa: ${rec.openTime || "--:--"} | Đóng cửa: ${rec.closeTime || "Đang mở"}`;

      // 1. Giờ vận hành thực tế
      const netH = Math.floor(m.netMin / 60);
      const netRemM = m.netMin % 60;
      const grossH = Math.floor(m.grossMin / 60);
      const grossRemM = m.grossMin % 60;
      const availPct = m.grossMin > 0 ? Math.round((m.netMin / m.grossMin) * 100) : 100;

      document.getElementById("kpiNetHours").textContent = `${netH}h ${String(netRemM).padStart(2, "0")}p`;
      document.getElementById("kpiGrossHours").textContent = `Khung mở cửa: ${grossH}h ${String(grossRemM).padStart(2, "0")}p`;
      document.getElementById("kpiAvailabilityPct").textContent = `Tỷ lệ hoạt động: ${availPct}%`;
      document.getElementById("kpiNetProgressBar").style.width = `${Math.min(100, availPct)}%`;

      // 2. Tổng thời gian dừng
      const downPct = m.grossMin > 0 ? Math.min(100, Math.round((m.totalDowntimeMin / m.grossMin) * 100)) : 0;
      document.getElementById("kpiDowntime").textContent = `${m.totalDowntimeMin} phút`;
      document.getElementById("kpiDowntimeCount").textContent = `Số lần dừng: ${rec.downtimes.length} lần`;
      document.getElementById("kpiDownProgressBar").style.width = `${downPct}%`;

      // Tìm nguyên nhân dừng lớn nhất
      const reasonTotals = {};
      rec.downtimes.forEach(d => {
        reasonTotals[d.reason] = (reasonTotals[d.reason] || 0) + (d.durationMin || 0);
      });
      let topReason = "Không có";
      let topReasonMin = 0;
      Object.entries(reasonTotals).forEach(([r, min]) => {
        if (min > topReasonMin) {
          topReasonMin = min;
          topReason = `${r} (${min}p)`;
        }
      });
      document.getElementById("kpiMainDowntimeReason").textContent = `Lỗi chính: ${topReason}`;

      // 3. Tổng số lượt chơi
      document.getElementById("kpiTotalCycles").textContent = `${formatVNNumber(m.totalCycles)} lượt`;
      document.getElementById("kpiCycleDetail").textContent = m.totalCycles > 0
        ? `Chu kỳ TB: ${formatDurationMMSS(m.avgCycleSec)} / lượt`
        : "Chu kỳ TB: --:-- / lượt";

      const singleCars = rec.cycles.filter(c => c.pax === 1).length;
      const doubleCars = rec.cycles.filter(c => c.pax === 2).length;
      if (rec.mode === "coaster") {
        document.getElementById("kpiCycleSubBreakdown").textContent = `Xe đơn: ${singleCars} | Xe đôi: ${doubleCars}`;
      } else {
        document.getElementById("kpiCycleSubBreakdown").textContent = `Đợt đón - tiễn khách: ${m.totalCycles} đợt`;
      }

      // 4. Tổng khách tham gia
      const avgPax = m.totalCycles > 0 ? (m.totalPax / m.totalCycles).toFixed(1) : "0";
      const paxPerHour = m.netMin > 0 ? Math.round((m.totalPax / m.netMin) * 60) : 0;
      document.getElementById("kpiTotalPax").textContent = `${formatVNNumber(m.totalPax)} khách`;
      document.getElementById("kpiPaxDetail").textContent = `TB: ${avgPax} khách / lượt`;
      document.getElementById("kpiPaxPerHour").textContent = `Năng suất: ${paxPerHour} khách / giờ`;

      // Phân tích thời gian dừng theo 6 nhóm nguyên nhân
      const dtGrid = document.getElementById("downtimeBreakdownGrid");
      dtGrid.innerHTML = DOWNTIME_REASONS.map(r => {
        const min = reasonTotals[r] || 0;
        const count = rec.downtimes.filter(d => d.reason === r).length;
        return `
          <div style="padding:10px 12px; border-radius:10px; border:1px solid #e2e8f0; background:${min > 0 ? '#fff5f5' : 'var(--surface-alt)'}; display:flex; justify-content:space-between; align-items:center;">
            <div>
              <div style="font-size:0.84rem; font-weight:700; color:var(--text);">${r}</div>
              <div style="font-size:0.75rem; color:var(--text-muted);">${count} lần phát sinh</div>
            </div>
            <div style="font-size:1.05rem; font-weight:800; color:${min > 0 ? 'var(--danger)' : 'var(--text-muted)'};">${min} phút</div>
          </div>
        `;
      }).join("");

      // Render Bảng tổng hợp 30 ô thẻ màu trên Dashboard khớp 100% với mẫu image_5b6f17.png
      const tileGrid = document.getElementById("allGamesTileGrid");
      const primaryMetric = document.getElementById("tilePrimaryMetricSelect")
        ? document.getElementById("tilePrimaryMetricSelect").value
        : "pax";
      const footerMode = document.getElementById("tileFooterModeSelect")
        ? document.getElementById("tileFooterModeSelect").value
        : "compare";

      const metricsById = {};
      ALL_GAMES.forEach(g => {
        const gRec = appStore.games[g.id] || createEmptyGameRecord(g.id, g.name, g.mode);
        const gm = computeGameMetrics(gRec);
        metricsById[g.id] = { rec: gRec, m: gm };
      });

      // Ô 1: MÁNG TRƯỢT (Tổng hợp Máng trượt 1 + 2 + 3)
      const c1 = metricsById["MANG_TRUOT_1"].m;
      const c2 = metricsById["MANG_TRUOT_2"].m;
      const c3 = metricsById["MANG_TRUOT_3"].m;
      const coasterTotalPax = c1.totalPax + c2.totalPax + c3.totalPax;
      const coasterSummary = {
        isSummary: true,
        id: "MANG_TRUOT_1",
        name: "MÁNG TRƯỢT",
        color: "#f43f5e",
        yesterdayPax: 1704,
        yesterdayShareDiff: coasterTotalPax === 0 ? "-100%" : "+10%",
        m: {
          netMin: c1.netMin + c2.netMin + c3.netMin,
          totalDowntimeMin: c1.totalDowntimeMin + c2.totalDowntimeMin + c3.totalDowntimeMin,
          totalCycles: c1.totalCycles + c2.totalCycles + c3.totalCycles,
          totalPax: coasterTotalPax
        }
      };

      const visibleGames = ALL_GAMES.filter(g => !g.hiddenIn30Grid);
      const cardsToRender = [
        coasterSummary,
        ...visibleGames.map(g => {
          let gm = metricsById[g.id].m;
          return {
            isSummary: false,
            id: g.id,
            name: g.name,
            color: g.color,
            yesterdayPax: g.yesterdayPax || 0,
            yesterdayShareDiff: gm.totalPax === 0 && (g.yesterdayPax || 0) > 0 ? "-100%" : (g.yesterdayShareDiff || "+0%"),
            m: gm
          };
        })
      ];

      tileGrid.innerHTML = cardsToRender.map(item => {
        const gm = item.m;
        const nh = Math.floor(gm.netMin / 60);
        const nm = gm.netMin % 60;
        const netHoursStr = `${nh}h${String(nm).padStart(2, "0")}p`;

        // Giá trị số lớn ở giữa thẻ
        let centerBigVal = formatVNNumber(gm.totalPax);
        if (primaryMetric === "cycles") {
          centerBigVal = formatVNNumber(gm.totalCycles);
        } else if (primaryMetric === "netHours") {
          centerBigVal = netHoursStr;
        } else if (primaryMetric === "downtime") {
          centerBigVal = `${gm.totalDowntimeMin}p`;
        }

        // Tính tỷ lệ khách chơi (%) trên tổng khách qua cổng (5.580)
        const sharePctNum = gm.totalPax > 0 ? ((gm.totalPax / BASE_GATE_VISITORS) * 100) : 0;
        const sharePctStr = sharePctNum.toFixed(1).replace(".", ",") + "%";

        // Tính +/- so với hôm qua
        let diffPctStr = "+0%";
        if (item.yesterdayPax > 0) {
          if (gm.totalPax === 0) {
            diffPctStr = "-100%";
          } else {
            const diffPct = Math.round(((gm.totalPax - item.yesterdayPax) / item.yesterdayPax) * 100);
            diffPctStr = (diffPct >= 0 ? `+${diffPct}%` : `${diffPct}%`);
          }
        }

        const isSelected = !item.isSummary && item.id === rec.gameId;

        let bottomHtml = "";
        if (footerMode === "compare") {
          bottomHtml = `
            <div class="tile-bottom">
              <div class="tile-Stat-row">
                <div class="tile-stat-col-left">
                  <span class="tile-stat-label">HÔM QUA</span>
                  <span class="tile-stat-val">${formatVNNumber(item.yesterdayPax)}</span>
                </div>
                <div class="tile-stat-col-right">
                  <span class="tile-stat-label">+/-</span>
                  <span class="tile-stat-val">${diffPctStr}</span>
                </div>
              </div>
              <div class="tile-Stat-row">
                <div class="tile-stat-col-left">
                  <span class="tile-stat-label">TỶ LỆ KHÁCH CHƠI</span>
                  <span class="tile-stat-val">${sharePctStr}</span>
                </div>
                <div class="tile-stat-col-right">
                  <span class="tile-stat-label">+/-</span>
                  <span class="tile-stat-val">${item.yesterdayShareDiff}</span>
                </div>
              </div>
            </div>
          `;
        } else {
          bottomHtml = `
            <div class="tile-bottom">
              <div class="tile-Stat-row">
                <div class="tile-stat-col-left">
                  <span class="tile-stat-label">GIỜ VH THỰC TẾ</span>
                  <span class="tile-stat-val">${netHoursStr}</span>
                </div>
                <div class="tile-stat-col-right">
                  <span class="tile-stat-label">TG DỪNG</span>
                  <span class="tile-stat-val">${gm.totalDowntimeMin} phút</span>
                </div>
              </div>
              <div class="tile-Stat-row">
                <div class="tile-stat-col-left">
                  <span class="tile-stat-label">TỔNG SỐ LƯỢT</span>
                  <span class="tile-stat-val">${formatVNNumber(gm.totalCycles)}</span>
                </div>
                <div class="tile-stat-col-right">
                  <span class="tile-stat-label">TỶ LỆ KHÁCH CHƠI</span>
                  <span class="tile-stat-val">${sharePctStr}</span>
                </div>
              </div>
            </div>
          `;
        }

        return `
          <div class="ops-color-tile ${isSelected ? 'selected-tile' : ''}" style="background:${item.color};" onclick="selectGameAndView('${item.id}')">
            <div class="tile-top">
              <div class="tile-title">${item.name}</div>
              <div class="tile-big-number">${centerBigVal}</div>
            </div>
            ${bottomHtml}
          </div>
        `;
      }).join("");
    }

    function renderDataEntryTables() {
      const rec = getCurrentRecord();

      updateDowntimePreview();

      const dtBody = document.getElementById("downtimeTableBody");
      if (rec.downtimes.length === 0) {
        dtBody.innerHTML = `<tr><td colspan="7" class="text-center" style="color:var(--text-muted); padding:12px;">Chưa có phát sinh ngừng vận hành trong ca</td></tr>`;
      } else {
        dtBody.innerHTML = rec.downtimes.map((d, idx) => `
          <tr>
            <td>${idx + 1}</td>
            <td><strong>${d.reason}</strong></td>
            <td>${d.start}</td>
            <td>${d.end}</td>
            <td class="text-right" style="font-weight:700; color:var(--danger);">${d.durationMin} phút</td>
            <td>${d.note || ""}</td>
            <td class="text-center"><button class="del-btn" onclick="deleteDowntime(${d.id})">✕</button></td>
          </tr>
        `).join("");
      }

      const cyHead = document.getElementById("cycleTableHead");
      const cyBody = document.getElementById("cycleTableBody");

      if (rec.mode === "coaster") {
        cyHead.innerHTML = `
          <tr>
            <th>Chuyến #</th>
            <th>Phân loại chuyến xe</th>
            <th>Giờ xuất phát</th>
            <th class="text-right">TG chuyến tiếp theo xuất phát</th>
            <th class="text-right">Công suất tải tức thời</th>
            <th class="text-right">Số khách</th>
            <th class="text-center">Xóa</th>
          </tr>
        `;
      } else {
        cyHead.innerHTML = `
          <tr>
            <th>Lượt #</th>
            <th>Phân loại lượt</th>
            <th>Bắt đầu đón khách</th>
            <th>Tiễn khách</th>
            <th class="text-right">Thời gian chu kỳ</th>
            <th class="text-right">Số khách</th>
            <th class="text-center">Xóa</th>
          </tr>
        `;
      }

      if (rec.cycles.length === 0) {
        cyBody.innerHTML = `<tr><td colspan="7" class="text-center" style="color:var(--text-muted); padding:12px;">Chưa có chuyến / lượt chơi nào được ghi nhận</td></tr>`;
      } else {
        cyBody.innerHTML = [...rec.cycles].reverse().map(c => {
          const areaBadge = c.subArea ? `<span class="subarea-Tag">${c.subArea}</span>` : "";
          if (rec.mode === "coaster") {
            const intervalText = c.durationSec > 0 ? `${formatDurationMMSS(c.durationSec)} (${c.durationSec}s)` : "Chuyến mở đầu";
            const capText = c.durationSec > 0 ? `~ ${Math.round(3600 / c.durationSec)} xe/giờ` : "--";
            return `
              <tr>
                <td><strong>#${c.cycleNo}</strong></td>
                <td>${areaBadge}${c.subType}</td>
                <td>${c.start}</td>
                <td class="text-right" style="font-weight:700; color:var(--accent);">${intervalText}</td>
                <td class="text-right" style="font-weight:700; color:var(--primary);">${capText}</td>
                <td class="text-right" style="font-weight:800; color:var(--success);">${formatVNNumber(c.pax)} khách</td>
                <td class="text-center"><button class="del-btn" onclick="deleteCycle(${c.id})">✕</button></td>
              </tr>
            `;
          } else {
            return `
              <tr>
                <td><strong>#${c.cycleNo}</strong></td>
                <td>${areaBadge}${c.subType}</td>
                <td>${c.start}</td>
                <td>${c.end}</td>
                <td class="text-right" style="font-weight:700;">${formatDurationMMSS(c.durationSec)}</td>
                <td class="text-right" style="font-weight:800; color:var(--success);">${formatVNNumber(c.pax)} khách</td>
                <td class="text-center"><button class="del-btn" onclick="deleteCycle(${c.id})">✕</button></td>
              </tr>
            `;
          }
        }).join("");
      }
    }

    function renderAll() {
      renderSubAreaSelector();
      renderDataEntryTables();
      renderActiveCoasterRuns();
      renderDashboard();
      renderStorageExplorer();
    }

    function loadDemoData() {
      populateSampleData();
      onGameChange();
    }

    function resetCurrentRideData() {
      showAppToast("Đã làm mới dữ liệu ca hiện tại của trò chơi!");
      const meta = getCurrentGameMeta();
      appStore.games[meta.id] = createEmptyGameRecord(meta.id, meta.name, meta.mode);
      activeCoasterCars = [];
      delete coasterLastDispatchState[meta.id];
      activeDowntimeState = null;
      batchCycleState = { running: false, startTimeMs: null, startStr: null };
      syncShiftDropdownsFromRecord(appStore.games[meta.id]);
      saveToLocalStorage();
      renderAll();
    }

    function exportCSV() {
      const rec = getCurrentRecord();
      const m = computeGameMetrics(rec);
      const nh = Math.floor(m.netMin / 60);
      const nm = m.netMin % 60;

      let lines = [];
      lines.push(["SUN WORLD - BÁO CÁO VẬN HÀNH TRÒ CHƠI"]);
      lines.push(["Trò chơi", rec.gameName]);
      lines.push(["Ngày vận hành", rec.date]);
      lines.push(["Nhân viên vận hành", rec.staff]);
      lines.push(["Thời gian mở cửa", rec.openTime || "Chưa chọn"]);
      lines.push(["Thời gian đóng cửa", rec.closeTime || "Chưa đóng ca"]);
      lines.push(["Giờ vận hành thực tế", `${nh}h ${String(nm).padStart(2, "0")}p`]);
      lines.push(["Tổng thời gian dừng (phút)", m.totalDowntimeMin]);
      lines.push(["Tổng số lượt chơi", m.totalCycles]);
      lines.push(["Tổng khách tham gia", m.totalPax]);
      lines.push([]);

      lines.push(["1. CHI TIẾT THỜI GIAN NGỪNG VẬN HÀNH"]);
      lines.push(["STT", "Nguyên nhân lỗi", "Giờ bắt đầu dừng", "Giờ hoạt động lại", "Số phút dừng", "Ghi chú"]);
      rec.downtimes.forEach((d, idx) => {
        lines.push([idx + 1, d.reason, d.start, d.end, d.durationMin, `"${(d.note || "").replace(/"/g, '""')}"`]);
      });
      lines.push([]);

      lines.push(["2. CHI TIẾT LƯỢT CHƠI & SỐ LƯỢNG KHÁCH"]);
      lines.push(["Lượt số", "Phân loại lượt", "Giờ bắt đầu", "Giờ hoàn thành", "Thời gian chu kỳ (giây)", "Thời gian chu kỳ (phút:giây)", "Số lượng khách"]);
      rec.cycles.forEach(c => {
        lines.push([c.cycleNo, c.subType, c.start, c.end, c.durationSec, formatDurationMMSS(c.durationSec), c.pax]);
      });

      const csvContent = "\uFEFF" + lines.map(r => r.join(",")).join("\n");
      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `SunWorld_VanHanh_${rec.gameId}_${rec.date}.csv`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }

    function exportAllGamesCSV() {
      const today = document.getElementById("opDate").value || new Date().toISOString().slice(0, 10);
      let lines = [];
      lines.push(["SUN WORLD - BÁO CÁO TỔNG QUAN 22 TRÒ CHƠI"]);
      lines.push(["Ngày xuất báo cáo", today]);
      lines.push([]);
      lines.push([
        "STT",
        "Trò chơi",
        "Nhân viên vận hành",
        "Thời gian mở cửa",
        "Thời gian đóng cửa",
        "Giờ vận hành thực tế",
        "Tổng thời gian dừng (phút)",
        "Tổng số lượt chơi",
        "Tổng khách tham gia"
      ]);

      ALL_GAMES.forEach((g, idx) => {
        const rec = appStore.games[g.id] || createEmptyGameRecord(g.id, g.name, g.mode);
        const m = computeGameMetrics(rec);
        const nh = Math.floor(m.netMin / 60);
        const nm = m.netMin % 60;
        lines.push([
          idx + 1,
          `"${g.name}"`,
          `"${rec.staff || ""}"`,
          rec.openTime || "--:--",
          rec.closeTime || "--:--",
          `${nh}h ${String(nm).padStart(2, "0")}p`,
          m.totalDowntimeMin,
          m.totalCycles,
          m.totalPax
        ]);
      });

      const csvContent = "\uFEFF" + lines.map(r => r.join(",")).join("\n");
      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `SunWorld_Dashboard_22TroChoi_${today}.csv`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }

    function updateLiveDateTimeHeader() {
      const now = new Date();
      const dd = String(now.getDate()).padStart(2, "0");
      const mm = String(now.getMonth() + 1).padStart(2, "0");
      const yyyy = now.getFullYear();
      const days = ["Chủ Nhật", "Thứ 2", "Thứ 3", "Thứ 4", "Thứ 5", "Thứ 6", "Thứ 7"];
      const dayName = days[now.getDay()];

      const dayEl = document.getElementById("liveDayNameDisplay");
      if (dayEl) dayEl.textContent = dayName;
      document.getElementById("liveDateDisplay").textContent = `${dd}/${mm}/${yyyy}`;
      document.getElementById("liveClock").textContent = now.toTimeString().slice(0, 8);
    }

    setInterval(() => {
      updateLiveDateTimeHeader();

      if (batchCycleState.running && batchCycleState.startTimeMs) {
        const sec = Math.floor((Date.now() - batchCycleState.startTimeMs) / 1000);
        document.getElementById("batchStopwatchDisplay").textContent = formatDurationMMSS(sec);
      }

      renderActiveCoasterRuns();
    }, 1000);

    window.addEventListener("click", () => {
      const panel = document.getElementById("notifDropdownPanel");
      if (panel) panel.classList.remove("open");
      const logoDd = document.getElementById("logoNavDropdown");
      if (logoDd) logoDd.classList.remove("open");
    });

    window.addEventListener("DOMContentLoaded", () => {
      const savedTheme = safeGetStorage("SUNWORLD_THEME_MODE") || "light";
      applyTheme(savedTheme);
      initTimeSelectDropdowns();
      initDefaultDemoIfEmpty();
      initIndexedDB();
      const savedWebhook = safeGetStorage("SUNWORLD_CLOUD_WEBHOOK_URL") || "";
      const webhookInput = document.getElementById("cloudWebhookUrlInput");
      if (webhookInput && savedWebhook) {
        webhookInput.value = savedWebhook;
        saveCloudWebhookUrl();
      }
      updateLiveDateTimeHeader();
      renderNotifications();
      document.getElementById("opDate").value = new Date().toISOString().slice(0, 10);
      onGameChange();
    });